        90: { base: { emoji: "🗣️", arText: "تَبَرَّأْ", trText: "İlişiğini kes / Uzaklaş!" } },
        91: { base: { emoji: "🙅", arText: "تَبَرُّؤ", trText: "İlişiğini kesme / Sorumluluk kabul etmeme." } }
