        77: { base: { emoji: "🌙", arText: "اِرْتَحَلَ", trText: "Göçtü, yola koyuldu; vefat etti" } },
        78: { base: { emoji: "🔁", arText: "يَرْتَحِلُ", trText: "Göçer, yola koyulur" } },
        79: { base: { emoji: "📣", arText: "اِرْتَحِلْ", trText: "Göç et!, yola koyul!" } },
