        38: { base: { emoji: "🟩", arText: "مَجَال", trText: "Alan, saha, meydan, imkân", ornek: { ar: "لَا مَجَالَ لِلشَّكِّ", tr: "Şüpheye yer yok." }, cogul: "مَجَالَات" } },
        88: { base: { emoji: "🧭", arText: "تَجَوَّلَ", trText: "Gezindi, etrafı dolaştı", ornek: { ar: "أَيْنَ تَجَوَّلْتِ فِي إِسْطَنْبُولَ؟", tr: "İstanbul'da nerede gezindin?" } } },
        89: { base: { emoji: "🔁", arText: "يَتَجَوَّلُ", trText: "Gezinir, dolaşır" } },
        90: { base: { emoji: "📣", arText: "تَجَوَّلْ", trText: "Gezin!, dolaş!" } },
        91: { base: { emoji: "📘", arText: "تَجَوُّل", trText: "Gezinme, dolaşma (masdar)" } },
        92: { base: { emoji: "🚐", arText: "مُتَجَوِّل", trText: "Gezgin, seyyar (satıcı)" } }
