        52: { base: { emoji: "⛵", arText: "أَبْحَرَ", trText: "Denize açıldı, gemiyle yola çıktı", ornek: { ar: "أَبْحَرَتِ السَّفِينَةُ إِلَى إِسْبَانْيَا", tr: "Gemi İspanya'ya doğru denize açıldı." } } },
        53: { base: { emoji: "🔁", arText: "يُبْحِرُ", trText: "Denize açılır" } },
