    /* 361 — ف ص ل : Ayırmak; mevsim, fasıl (2. bâb) */
    "فصل": {
        1: { base: { emoji: "✂️", arText: "فَصَلَ", trText: "Ayırdı, ayırt etti; azletti", ornek: { ar: "فَصَلَ الْمُعَلِّمُ الطُّلَّابَ إِلَى مَجْمُوعَتَيْنِ", tr: "Öğretmen öğrencileri iki gruba ayırdı." } }, not: "SEMANTİK ÇEKİRDEK: «ARAYA ÇİZGİ ÇEKMEK». فَصْل hem sınıfı (mekânı bölen oda) hem mevsimi (yılı bölen dilim) hem de mahkeme kararını (hakkı bâtıldan ayıran hüküm: يَوْمُ الْفَصْلِ) karşılar. تَفْصِيل ise bir bütünü parça parça açmaktır." },
        4: { base: { emoji: "🔁", arText: "يَفْصِلُ", trText: "Ayırır, ayırt eder" } },
        5: { base: { emoji: "📣", arText: "اِفْصِلْ", trText: "Ayır!" } },
        19: { base: { emoji: "🍂", arText: "فَصْل", trText: "Mevsim; sınıf, bölüm; ayırma, hüküm", ornek: { ar: "الْفُصُولُ أَرْبَعَةٌ", tr: "Mevsimler dörttür." }, cogul: "فُصُول" } },
        25: { tekilId: 19, base: { emoji: "🌦️", arText: "فُصُول", trText: "Mevsimler, bölümler (فَصْل çoğulu)", ornek: { ar: "فُصُولُ السَّنَةِ أَرْبَعَةٌ", tr: "Yılın mevsimleri dörttür." } } },
        33: { base: { emoji: "⚖️", arText: "فَاصِل", trText: "Ayıran, kesin; ara verme", ornek: { ar: "الْحَدُّ الْفَاصِلُ بَيْنَ الْبَلَدَيْنِ", tr: "İki ülke arasındaki ayırıcı sınır." } } },
        35: { base: { emoji: "📐", arText: "فَصِيل", trText: "Ayrı bölük, fasîle (grup)" } },
        58: { base: { emoji: "🧾", arText: "فَصَّلَ", trText: "Ayrıntılı anlattı, tafsil etti; (elbise) biçti" } },
        59: { base: { emoji: "🔁", arText: "يُفَصِّلُ", trText: "Ayrıntılandırır, tafsil eder" } },
        60: { base: { emoji: "📣", arText: "فَصِّلْ", trText: "Ayrıntılandır!" } },
        61: { base: { emoji: "📘", arText: "تَفْصِيل", trText: "Tafsilat, ayrıntı (masdar)", ornek: { ar: "اِشْرَحْ لِي بِالتَّفْصِيلِ", tr: "Bana ayrıntısıyla anlat." } } },
        71: { base: { emoji: "🔓", arText: "اِنْفَصَلَ", trText: "Ayrıldı, koptu" } },
        74: { base: { emoji: "📘", arText: "اِنْفِصَال", trText: "Ayrılma, kopma (masdar)" } }
    },

