        41: { tekilId: 20, base: { emoji: "👥", arText: "أَرْبَاب", trText: "Rabler, sahipler (رَبّ çoğulu)" } },
        58: { base: { emoji: "🧑‍🏫", arText: "رَبَّى", trText: "Terbiye etti, eğitti, büyüttü" } },
        61: { base: { emoji: "📘", arText: "تَرْبِيَة", trText: "Terbiye, eğitim (masdar)", ornek: { ar: "التَّرْبِيَةُ أَسَاسُ الْمُجْتَمَعِ", tr: "Eğitim toplumun temelidir." } } },
